'use client';

import React, { useState, useEffect } from 'react';
import { useAuth } from '@/lib/context/AuthContext';
import { Address } from '@/types';
import { MapPin, Plus, Edit2, Trash2, CheckCircle2, Home, Briefcase, Map, X } from 'lucide-react';
import { cn } from '@/lib/utils';

const ADDRESS_STORAGE_KEY = 'ozeira_addresses_v1';

export default function AddressesPage() {
  const { user } = useAuth();
  const [addresses, setAddresses] = useState<Address[]>([]);
  const [isFormOpen, setIsFormOpen] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);

  // Form State
  const [formData, setFormData] = useState<Partial<Address>>({
    address_type: 'home',
    is_default: false,
  });

  useEffect(() => {
    if (user) {
      const stored = localStorage.getItem(ADDRESS_STORAGE_KEY);
      if (stored) {
        const parsed = JSON.parse(stored) as Address[];
        setAddresses(parsed.filter(a => a.user_id === user.id));
      } else {
        const sample: Address = {
          id: 'addr-' + Date.now(),
          user_id: user.id,
          full_name: user.full_name,
          phone: user.phone || '9876543210',
          street: '123 Heritage Luxury Blvd',
          apartment: 'Suite 4B',
          city: 'Mumbai',
          state: 'Maharashtra',
          postal_code: '400050',
          country: 'India',
          is_default: true,
          address_type: 'home'
        };
        setAddresses([sample]);
        localStorage.setItem(ADDRESS_STORAGE_KEY, JSON.stringify([sample]));
      }
    }
  }, [user]);

  const saveAddresses = (newAddresses: Address[]) => {
    setAddresses(newAddresses);
    const stored = localStorage.getItem(ADDRESS_STORAGE_KEY);
    let all = stored ? JSON.parse(stored) : [];
    if (user) {
      all = all.filter((a: Address) => a.user_id !== user.id);
    }
    localStorage.setItem(ADDRESS_STORAGE_KEY, JSON.stringify([...all, ...newAddresses]));
  };

  if (!user) return null;

  const handleOpenAdd = () => {
    setEditingId(null);
    setFormData({
      full_name: user.full_name,
      phone: user.phone || '',
      street: '',
      apartment: '',
      city: '',
      state: '',
      postal_code: '',
      country: 'India',
      address_type: 'home',
      is_default: addresses.length === 0,
    });
    setIsFormOpen(true);
  };

  const handleOpenEdit = (addr: Address) => {
    setEditingId(addr.id);
    setFormData({ ...addr });
    setIsFormOpen(true);
  };

  const handleDelete = (id: string) => {
    if (confirm('Are you sure you want to remove this delivery address?')) {
      const remaining = addresses.filter(a => a.id !== id);
      if (remaining.length > 0 && addresses.find(a => a.id === id)?.is_default) {
        remaining[0].is_default = true;
      }
      saveAddresses(remaining);
    }
  };

  const handleSetDefault = (id: string) => {
    const updated = addresses.map(a => ({
      ...a,
      is_default: a.id === id
    }));
    saveAddresses(updated);
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.full_name || !formData.street || !formData.city || !formData.state || !formData.postal_code) {
      alert('Please fill in all mandatory address fields.');
      return;
    }

    let updated: Address[];
    if (editingId) {
      updated = addresses.map(a => {
        if (a.id === editingId) {
          return { ...a, ...formData } as Address;
        }
        return formData.is_default ? { ...a, is_default: false } : a;
      });
    } else {
      const newAddr: Address = {
        id: 'addr-' + Date.now(),
        user_id: user.id,
        full_name: formData.full_name || user.full_name,
        phone: formData.phone || '',
        street: formData.street || '',
        apartment: formData.apartment || '',
        city: formData.city || '',
        state: formData.state || '',
        postal_code: formData.postal_code || '',
        country: formData.country || 'India',
        address_type: formData.address_type || 'home',
        is_default: Boolean(formData.is_default || addresses.length === 0)
      };

      if (newAddr.is_default) {
        updated = addresses.map(a => ({ ...a, is_default: false }));
        updated.push(newAddr);
      } else {
        updated = [...addresses, newAddr];
      }
    }

    saveAddresses(updated);
    setIsFormOpen(false);
  };

  return (
    <div className="space-y-6">
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl font-serif font-bold text-stone-900 dark:text-stone-100 mb-1">Saved Addresses</h1>
          <p className="text-xs text-stone-500 dark:text-stone-400">Manage your shipping and billing delivery destinations.</p>
        </div>
        <button
          onClick={handleOpenAdd}
          className="inline-flex items-center gap-2 px-5 py-2.5 bg-[#1a1714] dark:bg-stone-800 hover:bg-[#c46331] text-white rounded-xl text-xs font-bold uppercase tracking-wider transition-colors cursor-pointer self-start sm:self-auto shadow-sm"
        >
          <Plus size={15} />
          <span>Add New Address</span>
        </button>
      </div>

      {/* Address Cards Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
        {addresses.map((addr) => (
          <div
            key={addr.id}
            className={cn(
              "p-6 rounded-3xl border bg-white dark:bg-[#16171b] shadow-sm relative flex flex-col justify-between transition-all",
              addr.is_default 
                ? "border-[#c46331] ring-1 ring-[#c46331]/30" 
                : "border-stone-200 dark:border-stone-800"
            )}
          >
            <div>
              <div className="flex items-center justify-between mb-3">
                <div className="flex items-center gap-2">
                  <span className="p-1.5 rounded-lg bg-amber-50 dark:bg-amber-950/50 text-[#c46331]">
                    {addr.address_type === 'work' ? <Briefcase size={14} /> : <Home size={14} />}
                  </span>
                  <span className="text-xs font-bold text-stone-900 dark:text-stone-100 capitalize">
                    {addr.address_type} Address
                  </span>
                </div>
                {addr.is_default && (
                  <span className="px-2.5 py-0.5 rounded-full text-[10px] font-bold uppercase tracking-wider bg-emerald-50 dark:bg-emerald-950/40 text-emerald-600 dark:text-emerald-400 border border-emerald-200 dark:border-emerald-800">
                    Default
                  </span>
                )}
              </div>

              <div className="text-xs text-stone-600 dark:text-stone-300 space-y-1">
                <p className="font-bold text-stone-900 dark:text-stone-100">{addr.full_name}</p>
                <p>{addr.street}</p>
                {addr.apartment && <p>{addr.apartment}</p>}
                <p>{addr.city}, {addr.state} {addr.postal_code}</p>
                <p>{addr.country}</p>
                <p className="pt-2 font-mono text-stone-400">Ph: {addr.phone}</p>
              </div>
            </div>

            <div className="flex items-center justify-between pt-4 mt-4 border-t border-stone-100 dark:border-stone-800 text-xs">
              <div>
                {!addr.is_default && (
                  <button
                    onClick={() => handleSetDefault(addr.id)}
                    className="text-[11px] text-stone-500 hover:text-[#c46331] font-semibold cursor-pointer"
                  >
                    Set as Default
                  </button>
                )}
              </div>
              <div className="flex items-center gap-3">
                <button
                  onClick={() => handleOpenEdit(addr)}
                  className="p-1.5 text-stone-400 hover:text-stone-800 dark:hover:text-stone-200 rounded-lg hover:bg-stone-100 dark:hover:bg-stone-800 transition-colors cursor-pointer"
                  title="Edit Address"
                >
                  <Edit2 size={14} />
                </button>
                <button
                  onClick={() => handleDelete(addr.id)}
                  className="p-1.5 text-stone-400 hover:text-rose-600 rounded-lg hover:bg-rose-50 dark:hover:bg-rose-950/30 transition-colors cursor-pointer"
                  title="Delete Address"
                >
                  <Trash2 size={14} />
                </button>
              </div>
            </div>
          </div>
        ))}
      </div>

      {/* Address Modal Drawer */}
      {isFormOpen && (
        <div className="fixed inset-0 bg-black/60 backdrop-blur-xs z-50 flex items-center justify-center p-4">
          <div className="bg-white dark:bg-[#16171b] rounded-3xl shadow-luxury max-w-lg w-full p-6 sm:p-8 border border-stone-200 dark:border-stone-800 space-y-5 animate-scale-in">
            <div className="flex items-center justify-between pb-3 border-b border-stone-100 dark:border-stone-800">
              <h3 className="text-base font-serif font-bold text-stone-900 dark:text-stone-100">
                {editingId ? 'Edit Delivery Address' : 'Add New Address'}
              </h3>
              <button
                onClick={() => setIsFormOpen(false)}
                className="p-1 text-stone-400 hover:text-stone-700 dark:hover:text-stone-200 cursor-pointer"
              >
                <X size={18} />
              </button>
            </div>

            <form onSubmit={handleSubmit} className="space-y-4 text-xs">
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                <div>
                  <label className="block font-semibold text-stone-700 dark:text-stone-300 mb-1">Full Name *</label>
                  <input
                    type="text"
                    required
                    value={formData.full_name || ''}
                    onChange={(e) => setFormData({ ...formData, full_name: e.target.value })}
                    className="w-full px-3 py-2 bg-stone-50 dark:bg-stone-900 border border-stone-200 dark:border-stone-700 rounded-xl text-stone-900 dark:text-stone-100 focus:outline-none focus:border-[#c46331]"
                  />
                </div>
                <div>
                  <label className="block font-semibold text-stone-700 dark:text-stone-300 mb-1">Phone Number *</label>
                  <input
                    type="tel"
                    required
                    value={formData.phone || ''}
                    onChange={(e) => setFormData({ ...formData, phone: e.target.value })}
                    className="w-full px-3 py-2 bg-stone-50 dark:bg-stone-900 border border-stone-200 dark:border-stone-700 rounded-xl text-stone-900 dark:text-stone-100 focus:outline-none focus:border-[#c46331]"
                  />
                </div>
              </div>

              <div>
                <label className="block font-semibold text-stone-700 dark:text-stone-300 mb-1">Street Address *</label>
                <input
                  type="text"
                  required
                  value={formData.street || ''}
                  onChange={(e) => setFormData({ ...formData, street: e.target.value })}
                  placeholder="House number, building, street"
                  className="w-full px-3 py-2 bg-stone-50 dark:bg-stone-900 border border-stone-200 dark:border-stone-700 rounded-xl text-stone-900 dark:text-stone-100 focus:outline-none focus:border-[#c46331]"
                />
              </div>

              <div>
                <label className="block font-semibold text-stone-700 dark:text-stone-300 mb-1">Apartment / Suite</label>
                <input
                  type="text"
                  value={formData.apartment || ''}
                  onChange={(e) => setFormData({ ...formData, apartment: e.target.value })}
                  placeholder="Apartment, suite, landmark (optional)"
                  className="w-full px-3 py-2 bg-stone-50 dark:bg-stone-900 border border-stone-200 dark:border-stone-700 rounded-xl text-stone-900 dark:text-stone-100 focus:outline-none focus:border-[#c46331]"
                />
              </div>

              <div className="grid grid-cols-3 gap-3">
                <div>
                  <label className="block font-semibold text-stone-700 dark:text-stone-300 mb-1">City *</label>
                  <input
                    type="text"
                    required
                    value={formData.city || ''}
                    onChange={(e) => setFormData({ ...formData, city: e.target.value })}
                    className="w-full px-3 py-2 bg-stone-50 dark:bg-stone-900 border border-stone-200 dark:border-stone-700 rounded-xl text-stone-900 dark:text-stone-100 focus:outline-none focus:border-[#c46331]"
                  />
                </div>
                <div>
                  <label className="block font-semibold text-stone-700 dark:text-stone-300 mb-1">State *</label>
                  <input
                    type="text"
                    required
                    value={formData.state || ''}
                    onChange={(e) => setFormData({ ...formData, state: e.target.value })}
                    className="w-full px-3 py-2 bg-stone-50 dark:bg-stone-900 border border-stone-200 dark:border-stone-700 rounded-xl text-stone-900 dark:text-stone-100 focus:outline-none focus:border-[#c46331]"
                  />
                </div>
                <div>
                  <label className="block font-semibold text-stone-700 dark:text-stone-300 mb-1">PIN Code *</label>
                  <input
                    type="text"
                    required
                    value={formData.postal_code || ''}
                    onChange={(e) => setFormData({ ...formData, postal_code: e.target.value })}
                    className="w-full px-3 py-2 bg-stone-50 dark:bg-stone-900 border border-stone-200 dark:border-stone-700 rounded-xl text-stone-900 dark:text-stone-100 focus:outline-none focus:border-[#c46331]"
                  />
                </div>
              </div>

              <div className="flex items-center gap-4 pt-2">
                <label className="flex items-center gap-2 cursor-pointer">
                  <input
                    type="radio"
                    name="address_type"
                    value="home"
                    checked={formData.address_type === 'home'}
                    onChange={() => setFormData({ ...formData, address_type: 'home' })}
                    className="text-[#c46331]"
                  />
                  <span className="text-xs text-stone-700 dark:text-stone-300 font-medium">Home</span>
                </label>
                <label className="flex items-center gap-2 cursor-pointer">
                  <input
                    type="radio"
                    name="address_type"
                    value="work"
                    checked={formData.address_type === 'work'}
                    onChange={() => setFormData({ ...formData, address_type: 'work' })}
                    className="text-[#c46331]"
                  />
                  <span className="text-xs text-stone-700 dark:text-stone-300 font-medium">Work / Office</span>
                </label>
              </div>

              <label className="flex items-center gap-2 cursor-pointer pt-1">
                <input
                  type="checkbox"
                  checked={formData.is_default}
                  onChange={(e) => setFormData({ ...formData, is_default: e.target.checked })}
                  className="rounded text-[#c46331]"
                />
                <span className="text-xs text-stone-700 dark:text-stone-300">Set as primary delivery address</span>
              </label>

              <div className="flex gap-3 pt-3">
                <button
                  type="button"
                  onClick={() => setIsFormOpen(false)}
                  className="flex-1 py-2.5 border border-stone-200 dark:border-stone-700 text-stone-700 dark:text-stone-300 rounded-xl text-xs font-semibold hover:bg-stone-100 dark:hover:bg-stone-800 transition-colors cursor-pointer"
                >
                  Cancel
                </button>
                <button
                  type="submit"
                  className="flex-1 py-2.5 bg-[#1a1714] dark:bg-stone-800 hover:bg-[#c46331] text-white rounded-xl text-xs font-bold uppercase tracking-wider transition-colors cursor-pointer shadow-sm"
                >
                  Save Address
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}

'use client';

import React, { useEffect } from 'react';
import { useRouter, usePathname } from 'next/navigation';
import Link from 'next/link';
import { useAuth } from '@/lib/context/AuthContext';
import { 
  User, 
  ShoppingBag, 
  Heart, 
  MapPin, 
  Award, 
  Users, 
  Settings, 
  LogOut,
  Menu,
  X,
  Sparkles,
  ShieldCheck,
  ExternalLink
} from 'lucide-react';
import { cn } from '@/lib/utils';

export default function AccountLayout({ children }: { children: React.ReactNode }) {
  const { user, isAuthenticated, logout } = useAuth();
  const router = useRouter();
  const pathname = usePathname();
  const [mobileMenuOpen, setMobileMenuOpen] = React.useState(false);

  useEffect(() => {
    if (!isAuthenticated) {
      router.push('/auth/login?redirect=' + encodeURIComponent(pathname));
    }
  }, [isAuthenticated, router, pathname]);

  if (!isAuthenticated || !user) {
    return (
      <div className="min-h-[70vh] flex items-center justify-center text-xs text-stone-400">
        Loading Atelier Account...
      </div>
    );
  }

  const navLinks = [
    { name: 'Overview', href: '/account', icon: User },
    { name: 'My Orders', href: '/account/orders', icon: ShoppingBag },
    { name: 'Wishlist', href: '/account/wishlist', icon: Heart },
    { name: 'Addresses', href: '/account/addresses', icon: MapPin },
    { name: 'Loyalty Points', href: '/account/loyalty', icon: Award },
    { name: 'Refer & Earn', href: '/account/referrals', icon: Users },
    { name: 'Settings', href: '/account/settings', icon: Settings },
  ];

  const handleLogout = () => {
    logout();
    router.push('/');
  };

  return (
    <div className="min-h-screen bg-stone-50 dark:bg-[#0f1014] pt-24 pb-16 transition-colors">
      <div className="container mx-auto px-4 max-w-6xl">
        <div className="flex flex-col md:flex-row gap-8">

          {/* Mobile Menu Toggle */}
          <div className="md:hidden flex justify-between items-center bg-white dark:bg-[#16171b] p-4 rounded-2xl shadow-sm border border-stone-200 dark:border-stone-800">
            <div className="flex items-center gap-3">
              <div className="w-10 h-10 rounded-full bg-amber-100 dark:bg-amber-950/60 flex items-center justify-center text-[#c46331] font-bold text-sm">
                {user.full_name.charAt(0)}
              </div>
              <div>
                <h2 className="font-semibold text-xs text-stone-900 dark:text-stone-100">{user.full_name}</h2>
                <p className="text-[11px] text-stone-400">{user.email}</p>
              </div>
            </div>
            <button 
              onClick={() => setMobileMenuOpen(!mobileMenuOpen)}
              className="p-2 text-stone-500 hover:text-[#c46331]"
            >
              {mobileMenuOpen ? <X size={20} /> : <Menu size={20} />}
            </button>
          </div>

          {/* Sidebar */}
          <aside className={cn(
            "w-full md:w-72 flex-shrink-0 transition-all duration-300 md:block",
            mobileMenuOpen ? "block" : "hidden"
          )}>
            <div className="bg-white dark:bg-[#16171b] rounded-3xl shadow-sm border border-stone-200 dark:border-stone-800 p-6 sticky top-28 space-y-6">
              {/* User Info (Desktop) */}
              <div className="hidden md:flex flex-col items-center text-center pb-6 border-b border-stone-100 dark:border-stone-800">
                <div className="w-16 h-16 rounded-full bg-amber-100 dark:bg-amber-950/60 flex items-center justify-center text-[#c46331] text-xl font-bold mb-3 shadow-xs">
                  {user.full_name.charAt(0)}
                </div>
                <h2 className="text-base font-serif font-bold text-stone-900 dark:text-stone-100">{user.full_name}</h2>
                <p className="text-xs text-stone-400 mb-3 truncate max-w-[200px]">{user.email}</p>

                {user.role === 'customer' ? (
                  <div className="inline-flex items-center gap-1.5 px-3 py-1 bg-amber-50 dark:bg-amber-950/50 text-[#c46331] dark:text-amber-400 rounded-full text-xs font-semibold border border-amber-200/60 dark:border-amber-900/40">
                    <Sparkles size={13} />
                    <span>{user.loyalty_points} Loyalty Points</span>
                  </div>
                ) : (
                  <div className="inline-flex items-center gap-1.5 px-3 py-1 bg-amber-100 dark:bg-amber-950/80 text-amber-900 dark:text-amber-300 rounded-full text-[10px] font-bold uppercase tracking-wider">
                    <ShieldCheck size={13} />
                    <span>{user.role === 'admin' ? 'Store Owner' : 'Order Staff'}</span>
                  </div>
                )}
              </div>

              {/* Admin Jump Button for Staff */}
              {(user.role === 'admin' || user.role === 'order_manager') && (
                <div className="pb-2">
                  <Link
                    href="/admin"
                    className="flex items-center justify-between px-3 py-2 bg-[#1a1714] dark:bg-stone-800 text-white rounded-xl text-xs font-bold hover:bg-[#c46331] transition-colors shadow-sm"
                  >
                    <span className="flex items-center gap-2">
                      <ShieldCheck className="w-4 h-4 text-amber-400" /> Admin Dashboard
                    </span>
                    <ExternalLink className="w-3.5 h-3.5" />
                  </Link>
                </div>
              )}

              {/* Navigation Links */}
              <nav className="flex flex-col gap-1">
                {navLinks.map((link) => {
                  const isActive = pathname === link.href;
                  const Icon = link.icon;
                  return (
                    <Link
                      key={link.name}
                      href={link.href}
                      onClick={() => setMobileMenuOpen(false)}
                      className={cn(
                        "flex items-center gap-3 px-3.5 py-2.5 rounded-xl text-xs font-semibold transition-all",
                        isActive 
                          ? "bg-amber-50 dark:bg-amber-950/40 text-[#c46331] dark:text-amber-400 font-bold" 
                          : "text-stone-600 dark:text-stone-400 hover:bg-stone-100 dark:hover:bg-stone-800/60 hover:text-stone-900 dark:hover:text-stone-200"
                      )}
                    >
                      <Icon size={16} className={isActive ? "text-[#c46331] dark:text-amber-400" : "text-stone-400"} />
                      <span>{link.name}</span>
                    </Link>
                  );
                })}

                <button
                  onClick={handleLogout}
                  className="flex items-center gap-3 px-3.5 py-2.5 rounded-xl text-xs font-semibold text-rose-600 dark:text-rose-400 hover:bg-rose-50 dark:hover:bg-rose-950/30 transition-all mt-4 text-left cursor-pointer"
                >
                  <LogOut size={16} />
                  <span>Sign Out</span>
                </button>
              </nav>
            </div>
          </aside>

          {/* Main Account Content Area */}
          <main className="flex-1 min-w-0">
            {children}
          </main>

        </div>
      </div>
    </div>
  );
}

'use client';

import React, { useEffect, useState } from 'react';
import Link from 'next/link';
import { useAuth } from '@/lib/context/AuthContext';
import { useCurrency } from '@/lib/context/CurrencyLanguageContext';
import { DataStore } from '@/lib/store/data-store';
import { supabase, isSupabaseConfigured } from '@/lib/supabase/client';
import { Order, OrderStatus } from '@/types';
import { formatDate } from '@/lib/utils';
import { cn } from '@/lib/utils';
import { Package, Search, Truck, ExternalLink, FileText, RotateCcw } from 'lucide-react';
import { RequestReturnModal } from '@/components/account/RequestReturnModal';

export default function OrdersPage() {
  const { user } = useAuth();
  const { formatAmount } = useCurrency();
  const [orders, setOrders] = useState<Order[]>([]);
  const [activeTab, setActiveTab] = useState<OrderStatus | 'all'>('all');
  const [loading, setLoading] = useState(true);
  const [selectedReturnOrder, setSelectedReturnOrder] = useState<Order | null>(null);

  const loadOrders = async () => {
    if (!user) return;
    const userEmail = user.email?.toLowerCase();
    let userOrders = DataStore.getOrders().filter(
      o => o.user_id === user.id || (userEmail && o.guest_email?.toLowerCase() === userEmail)
    );

    if (isSupabaseConfigured) {
      try {
        const { data: dbOrders } = await supabase
          .from('orders')
          .select('*')
          .or(`user_id.eq.${user.id},guest_email.ilike.${userEmail || 'none'}`)
          .order('created_at', { ascending: false });

        if (dbOrders && dbOrders.length > 0) {
          const map = new Map<string, Order>();
          userOrders.forEach(o => map.set(o.id, o));
          for (const dbo of dbOrders) {
            if (!map.has(dbo.id)) {
              map.set(dbo.id, { ...dbo, items: dbo.items || [], status_history: [] });
            }
          }
          userOrders = Array.from(map.values());
        }
      } catch (err) {
        console.error('Error fetching Supabase orders:', err);
      }
    }

    userOrders.sort((a, b) => new Date(b.created_at).getTime() - new Date(a.created_at).getTime());
    setOrders(userOrders);
    setLoading(false);
  };

  useEffect(() => {
    loadOrders();
  }, [user]);

  if (!user) return null;

  const tabs: { label: string; value: OrderStatus | 'all' }[] = [
    { label: 'All Orders', value: 'all' },
    { label: 'Pending', value: 'pending' },
    { label: 'Confirmed', value: 'confirmed' },
    { label: 'Shipped', value: 'shipped' },
    { label: 'Delivered', value: 'delivered' },
    { label: 'Cancelled', value: 'cancelled' },
  ];

  const filteredOrders = activeTab === 'all' 
    ? orders 
    : orders.filter(o => o.status === activeTab);

  const getStatusBadge = (status: string) => {
    switch(status) {
      case 'pending': return 'bg-amber-100 dark:bg-amber-950/60 text-amber-800 dark:text-amber-300';
      case 'confirmed': return 'bg-blue-100 dark:bg-blue-950/60 text-blue-800 dark:text-blue-300';
      case 'shipped': return 'bg-purple-100 dark:bg-purple-950/60 text-purple-800 dark:text-purple-300';
      case 'out_for_delivery': return 'bg-orange-100 dark:bg-orange-950/60 text-orange-800 dark:text-orange-300';
      case 'delivered': return 'bg-emerald-100 dark:bg-emerald-950/60 text-emerald-800 dark:text-emerald-300';
      case 'cancelled': return 'bg-rose-100 dark:bg-rose-950/60 text-rose-800 dark:text-rose-300';
      case 'return_requested': return 'bg-amber-100 dark:bg-amber-950/60 text-amber-800 dark:text-amber-300';
      case 'returned': return 'bg-stone-100 dark:bg-stone-800 text-stone-800 dark:text-stone-300';
      case 'refunded': return 'bg-teal-100 dark:bg-teal-950/60 text-teal-800 dark:text-teal-300';
      default: return 'bg-stone-100 dark:bg-stone-800 text-stone-800 dark:text-stone-300';
    }
  };

  return (
    <div className="space-y-6">
      <div>
        <h1 className="text-2xl font-serif font-bold text-stone-900 dark:text-stone-100 mb-1">My Orders</h1>
        <p className="text-xs text-stone-500 dark:text-stone-400">View and track all your bespoke atelier purchases.</p>
      </div>

      <div className="bg-white dark:bg-[#16171b] rounded-3xl shadow-sm border border-stone-200 dark:border-stone-800 overflow-hidden">
        {/* Tabs */}
        <div className="flex overflow-x-auto border-b border-stone-100 dark:border-stone-800 hide-scrollbar p-2">
          {tabs.map((tab) => (
            <button
              key={tab.value}
              onClick={() => setActiveTab(tab.value)}
              className={cn(
                "px-4 py-2 text-xs font-semibold rounded-xl whitespace-nowrap transition-colors",
                activeTab === tab.value
                  ? "bg-[#1a1714] dark:bg-amber-600 text-white shadow-sm"
                  : "text-stone-600 dark:text-stone-400 hover:bg-stone-100 dark:hover:bg-stone-800/60"
              )}
            >
              {tab.label}
            </button>
          ))}
        </div>

        {/* Content */}
        <div className="p-0">
          {loading ? (
            <div className="p-8 space-y-4">
              {[1, 2].map((i) => (
                <div key={i} className="h-32 bg-stone-100 dark:bg-stone-800/50 rounded-2xl animate-pulse" />
              ))}
            </div>
          ) : filteredOrders.length === 0 ? (
            <div className="p-12 text-center flex flex-col items-center justify-center space-y-3">
              <div className="w-12 h-12 bg-stone-100 dark:bg-stone-800 rounded-full flex items-center justify-center text-stone-400">
                <Search size={22} />
              </div>
              <h3 className="text-sm font-bold text-stone-900 dark:text-stone-100">No orders found</h3>
              <p className="text-xs text-stone-500 dark:text-stone-400 max-w-xs">
                {activeTab === 'all' 
                  ? "You haven't placed any orders yet." 
                  : `You have no ${activeTab.replace(/_/g, ' ')} orders.`}
              </p>
              <Link
                href="/shop"
                className="px-6 py-2.5 bg-[#1a1714] dark:bg-amber-600 text-white rounded-xl text-xs font-bold uppercase tracking-wider hover:bg-[#c46331] transition-colors"
              >
                Start Shopping →
              </Link>
            </div>
          ) : (
            <div className="divide-y divide-stone-100 dark:divide-stone-800">
              {filteredOrders.map((order) => (
                <div key={order.id} className="p-6">
                  <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-4 gap-4">
                    <div>
                      <div className="flex items-center gap-3 mb-1">
                        <h3 className="text-sm font-bold text-stone-900 dark:text-stone-100">Order #{order.order_number}</h3>
                        <span className={cn("px-2.5 py-0.5 rounded-full text-[10px] font-bold uppercase tracking-wider", getStatusBadge(order.status))}>
                          {order.status.replace(/_/g, ' ')}
                        </span>
                      </div>
                      <p className="text-xs text-stone-500 dark:text-stone-400">
                        Placed on {formatDate(order.created_at)}
                      </p>
                    </div>

                    <div className="flex flex-wrap gap-2 w-full md:w-auto">
                      {/* Download Tax Invoice Link */}
                      <a
                        href={`/api/invoice/${order.id}`}
                        target="_blank"
                        rel="noopener noreferrer"
                        className="flex items-center gap-1.5 px-3.5 py-2 bg-stone-100 dark:bg-stone-800 hover:bg-stone-200 dark:hover:bg-stone-700 text-stone-800 dark:text-stone-200 rounded-xl text-xs font-semibold transition-colors"
                      >
                        <FileText size={14} className="text-[#c46331]" />
                        <span>Tax Invoice</span>
                      </a>

                      {/* Track Shipment Link */}
                      <Link 
                        href={`/track-order?orderNumber=${order.order_number}&email=${encodeURIComponent(user.email || '')}`}
                        className="flex items-center gap-1.5 px-3.5 py-2 bg-stone-100 dark:bg-stone-800 hover:bg-[#c46331] hover:text-white text-stone-800 dark:text-stone-200 rounded-xl text-xs font-semibold transition-colors"
                      >
                        <Truck size={14} />
                        <span>Track</span>
                      </Link>

                      {/* Return / Exchange Trigger for Delivered Orders */}
                      {(order.status === 'delivered') && (
                        <button
                          onClick={() => setSelectedReturnOrder(order)}
                          className="flex items-center gap-1.5 px-3.5 py-2 bg-amber-50 dark:bg-amber-950/40 hover:bg-[#c46331] hover:text-white text-[#c46331] dark:text-amber-300 border border-amber-200 dark:border-amber-900/50 rounded-xl text-xs font-semibold transition-colors"
                        >
                          <RotateCcw size={14} />
                          <span>Return / Exchange</span>
                        </button>
                      )}
                    </div>
                  </div>

                  <div className="bg-stone-50 dark:bg-stone-900 rounded-2xl p-4 flex flex-col sm:flex-row items-center gap-4 border border-stone-200/60 dark:border-stone-800">
                    <div className="flex -space-x-2 overflow-hidden shrink-0">
                      {(order.items || []).slice(0, 3).map((item, idx) => (
                        <div key={idx} className="inline-block h-12 w-12 rounded-xl ring-2 ring-white dark:ring-stone-900 bg-stone-100 dark:bg-stone-800 overflow-hidden">
                          {item.product_image && (
                            <img src={item.product_image} alt={item.product_title} className="w-full h-full object-cover" />
                          )}
                        </div>
                      ))}
                      {(order.items || []).length > 3 && (
                        <div className="inline-flex items-center justify-center h-12 w-12 rounded-xl ring-2 ring-white dark:ring-stone-900 bg-stone-200 dark:bg-stone-800 text-xs font-bold text-stone-600 dark:text-stone-300">
                          +{(order.items || []).length - 3}
                        </div>
                      )}
                    </div>

                    <div className="flex-1 text-xs text-stone-600 dark:text-stone-300">
                      <p>
                        {(order.items || []).length} item(s) • Total: <span className="font-bold text-stone-900 dark:text-stone-100">{formatAmount(order.total_amount)}</span>
                      </p>
                      {(order.items || []).slice(0, 1).map(item => (
                        <p key={item.id} className="text-[11px] text-stone-400 truncate mt-0.5">
                          Includes: {item.product_title} {(order.items || []).length > 1 ? '& more' : ''}
                        </p>
                      ))}
                    </div>
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>
      </div>

      {/* Return Request Modal */}
      {selectedReturnOrder && (
        <RequestReturnModal
          order={selectedReturnOrder}
          isOpen={!!selectedReturnOrder}
          onClose={() => setSelectedReturnOrder(null)}
          onSuccess={() => {
            loadOrders();
          }}
        />
      )}
    </div>
  );
}

'use client';

import React, { useEffect, useState } from 'react';
import Link from 'next/link';
import { useParams } from 'next/navigation';
import { DataStore } from '@/lib/store/data-store';
import { useCurrency } from '@/lib/context/CurrencyLanguageContext';
import { Order, OrderStatus } from '@/types';
import { formatDateTime } from '@/lib/utils';
import { cn } from '@/lib/utils';
import { supabase, isSupabaseConfigured } from '@/lib/supabase/client';
import { 
  ArrowLeft, 
  CheckCircle2, 
  Clock, 
  Package, 
  Truck, 
  Home,
  XCircle,
  AlertCircle,
  ExternalLink,
  ShieldCheck
} from 'lucide-react';

export default function OrderTrackPage() {
  const routeParams = useParams();
  const rawId = routeParams?.id;
  const id = Array.isArray(rawId) ? rawId[0] : (rawId as string) || '';
  const { formatAmount } = useCurrency();
  const [order, setOrder] = useState<Order | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    async function fetchOrder() {
      if (!id) {
        setLoading(false);
        return;
      }
      setLoading(true);
      const local = DataStore.getOrderById(id) || DataStore.getOrders().find(o => o.order_number === id);
      if (local) {
        setOrder(local);
        setLoading(false);
        return;
      }

      if (isSupabaseConfigured) {
        try {
          const { data, error } = await supabase
            .from('orders')
            .select('*, items:order_items(*), status_history:order_status_history(*)')
            .or(`id.eq.${id},order_number.eq.${id}`)
            .maybeSingle();

          if (data && !error) {
            setOrder(data as Order);
          } else {
            setOrder(null);
          }
        } catch (err) {
          console.error('Track fetch error:', err);
          setOrder(null);
        }
      } else {
        setOrder(null);
      }
      setLoading(false);
    }

    fetchOrder();
  }, [id]);

  if (loading) {
    return (
      <div className="bg-white dark:bg-[#14151a] rounded-2xl border border-neutral-200 dark:border-neutral-800 p-12 text-center shadow-sm">
        <div className="inline-block w-8 h-8 border-2 border-brand-amber border-t-transparent rounded-full animate-spin mb-4" />
        <p className="text-neutral-600 dark:text-neutral-400 font-sans text-sm">Querying real-time courier telemetry...</p>
      </div>
    );
  }

  if (!order) {
    return (
      <div className="bg-white dark:bg-[#14151a] rounded-2xl border border-neutral-200 dark:border-neutral-800 p-12 text-center space-y-4 shadow-sm">
        <AlertCircle size={48} className="mx-auto text-red-500 mb-2" />
        <h2 className="text-xl font-serif font-bold text-neutral-900 dark:text-neutral-100">Order Not Located</h2>
        <p className="text-neutral-500 dark:text-neutral-400 max-w-md mx-auto text-sm">
          The requested identifier could not be matched with an active consignment. Please verify the order number.
        </p>
        <div className="pt-2">
          <Link
            href="/account/orders"
            className="inline-flex items-center px-6 py-2.5 bg-neutral-900 hover:bg-neutral-800 dark:bg-neutral-100 dark:hover:bg-white text-white dark:text-neutral-900 rounded-xl text-sm font-medium transition-all shadow-sm"
          >
            Return to Order Ledger
          </Link>
        </div>
      </div>
    );
  }

  const statusOrder: OrderStatus[] = ['pending', 'confirmed', 'shipped', 'out_for_delivery', 'delivered'];
  const isCancelled = order.status === 'cancelled' || order.status === 'returned';
  const currentIndex = isCancelled ? -1 : statusOrder.indexOf(order.status);

  const getStatusIcon = (status: OrderStatus, index: number) => {
    if (isCancelled) {
      if (status === 'pending') return <CheckCircle2 size={22} className="text-neutral-400 dark:text-neutral-600" />;
      return <XCircle size={22} className="text-red-500" />;
    }

    if (index < currentIndex) return <CheckCircle2 size={22} className="text-emerald-500" />;
    if (index === currentIndex) {
      switch(status) {
        case 'pending': return <Clock size={22} className="text-amber-500 animate-pulse" />;
        case 'confirmed': return <ShieldCheck size={22} className="text-blue-500" />;
        case 'shipped': return <Package size={22} className="text-purple-500" />;
        case 'out_for_delivery': return <Truck size={22} className="text-brand-amber animate-bounce" />;
        case 'delivered': return <Home size={22} className="text-emerald-500" />;
      }
    }
    return <div className="w-5 h-5 rounded-full border-2 border-neutral-300 dark:border-neutral-700" />;
  };

  const getStatusLabel = (status: OrderStatus) => {
    switch(status) {
      case 'pending': return 'Order Placed';
      case 'confirmed': return 'Verified & Confirmed';
      case 'shipped': return 'Dispatched from Atelier';
      case 'out_for_delivery': return 'Out for Delivery';
      case 'delivered': return 'Delivered to Patron';
      default: return status;
    }
  };

  const getStatusTimestamp = (status: OrderStatus) => {
    if (!order.status_history) return null;
    const history = order.status_history.find(h => h.status === status);
    return history ? formatDateTime(history.created_at) : null;
  };

  const items = order.items || [];

  return (
    <div className="space-y-6">
      {/* Top Header */}
      <div>
        <Link
          href="/account/orders"
          className="inline-flex items-center text-xs font-semibold uppercase tracking-wider text-neutral-500 hover:text-brand-amber dark:text-neutral-400 dark:hover:text-brand-amber mb-3 transition-colors"
        >
          <ArrowLeft size={14} className="mr-1.5" /> Back to Orders
        </Link>
        <div className="flex flex-col md:flex-row md:items-end justify-between gap-4">
          <div>
            <h1 className="text-2xl sm:text-3xl font-serif text-neutral-900 dark:text-neutral-100">
              Live Consignment #{order.order_number}
            </h1>
            <p className="text-neutral-500 dark:text-neutral-400 text-xs sm:text-sm mt-1">
              Registered on {formatDateTime(order.created_at)}
            </p>
          </div>
          <div className="flex flex-wrap items-center gap-3">
            <div className="px-3.5 py-1.5 rounded-xl border border-neutral-200 dark:border-neutral-800 bg-neutral-50 dark:bg-neutral-900/50 text-xs">
              <span className="text-neutral-400 mr-1.5 uppercase font-mono">Payment:</span>
              <span className="font-semibold text-neutral-900 dark:text-neutral-100 uppercase">{order.payment_method}</span>
            </div>
            <div className="px-3.5 py-1.5 rounded-xl border border-brand-amber/20 bg-brand-amber/10 text-xs">
              <span className="text-neutral-400 dark:text-neutral-500 mr-1.5 uppercase font-mono">Status:</span>
              <span className="font-semibold text-brand-amber capitalize">{order.payment_status}</span>
            </div>
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* Timeline Column */}
        <div className="lg:col-span-2 space-y-6">
          <div className="bg-white dark:bg-[#14151a] rounded-2xl border border-neutral-200 dark:border-neutral-800 p-6 sm:p-8 shadow-sm">
            <div className="flex items-center justify-between pb-6 border-b border-neutral-100 dark:border-neutral-800/80 mb-6">
              <div>
                <h2 className="text-lg font-serif font-semibold text-neutral-900 dark:text-neutral-100">Fulfillment Progression</h2>
                <p className="text-xs text-neutral-500 dark:text-neutral-400 mt-0.5">End-to-end telemetry from our master workshop</p>
              </div>
              <span className="text-xs font-mono px-2.5 py-1 rounded-full uppercase bg-neutral-100 dark:bg-neutral-800 text-neutral-700 dark:text-neutral-300 font-semibold">
                {order.status.replace(/_/g, ' ')}
              </span>
            </div>

            {isCancelled ? (
              <div className="flex items-start gap-4 mb-8 text-red-600 dark:text-red-400 bg-red-50 dark:bg-red-950/30 p-4 rounded-xl border border-red-200 dark:border-red-900/40">
                <XCircle size={24} className="shrink-0 mt-0.5" />
                <div>
                  <h3 className="font-bold text-sm">Order {order.status.charAt(0).toUpperCase() + order.status.slice(1)}</h3>
                  <p className="text-xs text-red-700 dark:text-red-300 mt-0.5">This shipment has been cancelled or recalled to the archive vault.</p>
                </div>
              </div>
            ) : null}

            <div className="relative pl-2 sm:pl-4">
              {/* Vertical line connecting steps */}
              {!isCancelled && (
                <div className="absolute left-[18px] sm:left-[26px] top-4 bottom-8 w-0.5 bg-neutral-200 dark:bg-neutral-800" />
              )}

              <div className="space-y-7 relative">
                {(isCancelled ? (['pending', order.status] as OrderStatus[]) : statusOrder).map((status, index) => {
                  const isCompleted = isCancelled ? index === 0 : index <= currentIndex;
                  const isCurrent = isCancelled ? index === 1 : index === currentIndex;
                  const timestamp = getStatusTimestamp(status);
                  const notes = order.status_history?.find(h => h.status === status)?.notes;

                  return (
                    <div
                      key={status}
                      className={cn(
                        "flex gap-4 relative transition-opacity",
                        !isCompleted && !isCurrent ? "opacity-40" : ""
                      )}
                    >
                      {/* Status Icon container */}
                      <div className="relative z-10 shrink-0 bg-white dark:bg-[#14151a] py-1 flex items-center justify-center">
                        {getStatusIcon(status, index)}
                      </div>

                      {/* Content */}
                      <div className="pt-0.5 pb-2 flex-1">
                        <div className="flex flex-col sm:flex-row sm:justify-between sm:items-start gap-1 sm:gap-4">
                          <h3 className={cn(
                            "font-medium text-sm sm:text-base",
                            isCurrent ? "text-brand-amber font-semibold" : "text-neutral-900 dark:text-neutral-100"
                          )}>
                            {getStatusLabel(status)}
                          </h3>
                          {timestamp && (
                            <span className="text-xs font-mono text-neutral-400 dark:text-neutral-500 whitespace-nowrap">
                              {timestamp}
                            </span>
                          )}
                        </div>
                        {notes && (
                          <p className="text-xs sm:text-sm text-neutral-600 dark:text-neutral-400 mt-1">{notes}</p>
                        )}

                        {/* Courier Details */}
                        {isCurrent && (status === 'shipped' || status === 'out_for_delivery') && order.tracking_number && (
                          <div className="mt-3 bg-neutral-50 dark:bg-neutral-900/60 rounded-xl p-4 text-xs sm:text-sm border border-neutral-200/80 dark:border-neutral-800">
                            <p className="font-semibold text-neutral-900 dark:text-neutral-100 mb-1.5 flex items-center gap-1.5">
                              <Truck size={14} className="text-brand-amber" /> Courier Manifest
                            </p>
                            <p className="text-neutral-600 dark:text-neutral-400">Partner: <span className="font-medium text-neutral-900 dark:text-neutral-200">{order.tracking_courier || 'Express Atelier Logistics'}</span></p>
                            <p className="text-neutral-600 dark:text-neutral-400 mt-0.5">AWB / Consignment: <span className="font-mono font-medium text-neutral-900 dark:text-neutral-200">{order.tracking_number}</span></p>
                            {order.tracking_url && (
                              <a
                                href={order.tracking_url}
                                target="_blank"
                                rel="noreferrer"
                                className="inline-flex items-center gap-1 text-brand-amber hover:underline font-semibold mt-2.5 text-xs"
                              >
                                View Carrier Tracking Portal <ExternalLink size={12} />
                              </a>
                            )}
                          </div>
                        )}
                      </div>
                    </div>
                  );
                })}
              </div>
            </div>
          </div>
        </div>

        {/* Sidebar Summary */}
        <div className="space-y-6">
          {/* Order Items Summary */}
          <div className="bg-white dark:bg-[#14151a] rounded-2xl border border-neutral-200 dark:border-neutral-800 p-6 shadow-sm">
            <h2 className="font-serif font-semibold text-neutral-900 dark:text-neutral-100 mb-4 pb-3 border-b border-neutral-100 dark:border-neutral-800">
              Curated Selection ({items.length})
            </h2>
            <div className="space-y-3.5">
              {items.map((item) => (
                <div key={item.id} className="flex gap-3 items-center">
                  <div className="w-14 h-14 rounded-xl overflow-hidden bg-neutral-100 dark:bg-neutral-800 shrink-0 border border-neutral-200 dark:border-neutral-700">
                    <img src={item.product_image} alt={item.product_title} className="w-full h-full object-cover" />
                  </div>
                  <div className="flex-1 min-w-0">
                    <p className="text-xs font-medium text-neutral-900 dark:text-neutral-100 truncate">{item.product_title}</p>
                    <p className="text-[11px] text-neutral-500 dark:text-neutral-400">Qty: {item.quantity} {item.variant_details?.size ? `• Size: ${item.variant_details.size}` : ''}</p>
                    <p className="text-xs font-semibold text-brand-amber mt-0.5">{formatAmount(item.unit_price)}</p>
                  </div>
                </div>
              ))}
            </div>

            <div className="border-t border-neutral-100 dark:border-neutral-800 mt-5 pt-4 space-y-2 text-xs">
              <div className="flex justify-between text-neutral-600 dark:text-neutral-400">
                <span>Subtotal</span>
                <span>{formatAmount(order.subtotal)}</span>
              </div>
              {order.discount_amount > 0 && (
                <div className="flex justify-between text-emerald-600 dark:text-emerald-400">
                  <span>Privilege Discount</span>
                  <span>-{formatAmount(order.discount_amount)}</span>
                </div>
              )}
              {order.loyalty_discount_amount > 0 && (
                <div className="flex justify-between text-brand-amber">
                  <span>Points Redeemed</span>
                  <span>-{formatAmount(order.loyalty_discount_amount)}</span>
                </div>
              )}
              <div className="flex justify-between text-neutral-600 dark:text-neutral-400">
                <span>Insured Express Delivery</span>
                <span>{order.shipping_fee === 0 ? 'Complimentary' : formatAmount(order.shipping_fee)}</span>
              </div>
              <div className="flex justify-between font-bold text-sm text-neutral-900 dark:text-neutral-100 pt-3 border-t border-neutral-100 dark:border-neutral-800 mt-2">
                <span>Total Invoiced</span>
                <span className="text-brand-amber">{formatAmount(order.total_amount)}</span>
              </div>
            </div>
          </div>

          {/* Delivery Address */}
          {order.shipping_address && (
            <div className="bg-white dark:bg-[#14151a] rounded-2xl border border-neutral-200 dark:border-neutral-800 p-6 shadow-sm">
              <h2 className="font-serif font-semibold text-neutral-900 dark:text-neutral-100 mb-3 pb-2 border-b border-neutral-100 dark:border-neutral-800 text-sm">
                Consignee Destination
              </h2>
              <div className="text-xs text-neutral-600 dark:text-neutral-400 space-y-1">
                <p className="font-semibold text-neutral-900 dark:text-neutral-100">{order.shipping_address.full_name}</p>
                <p>{order.shipping_address.street}</p>
                {order.shipping_address.apartment && <p>{order.shipping_address.apartment}</p>}
                <p>{order.shipping_address.city}, {order.shipping_address.state} {order.shipping_address.postal_code}</p>
                <p className="pt-1.5 text-neutral-500">Phone: {order.shipping_address.phone}</p>
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

'use client';

import React, { useEffect, useState } from 'react';
import Link from 'next/link';
import { useAuth } from '@/lib/context/AuthContext';
import { useCurrency } from '@/lib/context/CurrencyLanguageContext';
import { useWishlist } from '@/lib/context/WishlistContext';
import { DataStore } from '@/lib/store/data-store';
import { Order, Referral } from '@/types';
import { ShoppingBag, Award, Heart, Users, ChevronRight, ArrowRight, Truck } from 'lucide-react';
import { formatDate } from '@/lib/utils';
import { cn } from '@/lib/utils';

export default function AccountOverviewPage() {
  const { user } = useAuth();
  const { formatAmount } = useCurrency();
  const { count: wishlistCount } = useWishlist();

  const [orders, setOrders] = useState<Order[]>([]);
  const [referrals, setReferrals] = useState<Referral[]>([]);

  useEffect(() => {
    if (user) {
      const userOrders = DataStore.getOrders().filter(o => o.user_id === user.id);
      userOrders.sort((a, b) => new Date(b.created_at).getTime() - new Date(a.created_at).getTime());
      setOrders(userOrders);

      const userReferrals = DataStore.getReferrals(user.id);
      setReferrals(userReferrals);
    }
  }, [user]);

  if (!user) {
    return (
      <div className="space-y-6 animate-pulse">
        <div className="bg-white dark:bg-[#16171b] rounded-3xl p-8 h-32 border border-stone-200 dark:border-stone-800" />
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
          {[1, 2, 3, 4].map((i) => (
            <div key={i} className="bg-white dark:bg-[#16171b] rounded-2xl p-5 h-28 border border-stone-200 dark:border-stone-800" />
          ))}
        </div>
      </div>
    );
  }

  const recentOrders = orders.slice(0, 3);

  const getStatusBadge = (status: string) => {
    switch(status) {
      case 'pending': return 'bg-amber-100 dark:bg-amber-950/60 text-amber-800 dark:text-amber-300';
      case 'confirmed': return 'bg-blue-100 dark:bg-blue-950/60 text-blue-800 dark:text-blue-300';
      case 'shipped': return 'bg-purple-100 dark:bg-purple-950/60 text-purple-800 dark:text-purple-300';
      case 'out_for_delivery': return 'bg-orange-100 dark:bg-orange-950/60 text-orange-800 dark:text-orange-300';
      case 'delivered': return 'bg-emerald-100 dark:bg-emerald-950/60 text-emerald-800 dark:text-emerald-300';
      case 'cancelled': return 'bg-rose-100 dark:bg-rose-950/60 text-rose-800 dark:text-rose-300';
      case 'returned': return 'bg-stone-100 dark:bg-stone-800 text-stone-800 dark:text-stone-300';
      default: return 'bg-stone-100 dark:bg-stone-800 text-stone-800 dark:text-stone-300';
    }
  };

  return (
    <div className="space-y-6">
      {/* Welcome Banner */}
      <div className="bg-white dark:bg-[#16171b] rounded-3xl shadow-sm border border-stone-200 dark:border-stone-800 p-6 md:p-8">
        <h1 className="text-2xl font-serif font-bold text-stone-900 dark:text-stone-100 mb-1">
          Welcome back, {user.full_name}!
        </h1>
        <p className="text-xs text-stone-500 dark:text-stone-400">
          Manage your bespoke orders, luxury wishlist, and loyalty benefits from your atelier portal.
        </p>
      </div>

      {/* Metrics Row */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
        <div className="bg-white dark:bg-[#16171b] p-5 rounded-3xl shadow-sm border border-stone-200 dark:border-stone-800 flex items-center gap-4">
          <div className="w-11 h-11 rounded-2xl bg-amber-100 dark:bg-amber-950/60 flex items-center justify-center text-[#c46331] shrink-0">
            <ShoppingBag size={20} />
          </div>
          <div>
            <p className="text-[11px] text-stone-500 dark:text-stone-400 font-semibold uppercase tracking-wider">Total Orders</p>
            <p className="text-xl font-bold text-stone-900 dark:text-stone-100">{orders.length}</p>
          </div>
        </div>

        <div className="bg-white dark:bg-[#16171b] p-5 rounded-3xl shadow-sm border border-stone-200 dark:border-stone-800 flex items-center gap-4">
          <div className="w-11 h-11 rounded-2xl bg-amber-100 dark:bg-amber-950/60 flex items-center justify-center text-[#c46331] shrink-0">
            <Award size={20} />
          </div>
          <div>
            <p className="text-[11px] text-stone-500 dark:text-stone-400 font-semibold uppercase tracking-wider">Loyalty Points</p>
            <p className="text-xl font-bold text-stone-900 dark:text-stone-100">{user.loyalty_points}</p>
          </div>
        </div>

        <div className="bg-white dark:bg-[#16171b] p-5 rounded-3xl shadow-sm border border-stone-200 dark:border-stone-800 flex items-center gap-4">
          <div className="w-11 h-11 rounded-2xl bg-rose-100 dark:bg-rose-950/60 flex items-center justify-center text-rose-600 shrink-0">
            <Heart size={20} />
          </div>
          <div>
            <p className="text-[11px] text-stone-500 dark:text-stone-400 font-semibold uppercase tracking-wider">Wishlist Items</p>
            <p className="text-xl font-bold text-stone-900 dark:text-stone-100">{wishlistCount}</p>
          </div>
        </div>

        <div className="bg-white dark:bg-[#16171b] p-5 rounded-3xl shadow-sm border border-stone-200 dark:border-stone-800 flex items-center gap-4">
          <div className="w-11 h-11 rounded-2xl bg-blue-100 dark:bg-blue-950/60 flex items-center justify-center text-blue-600 shrink-0">
            <Users size={20} />
          </div>
          <div>
            <p className="text-[11px] text-stone-500 dark:text-stone-400 font-semibold uppercase tracking-wider">Referrals</p>
            <p className="text-xl font-bold text-stone-900 dark:text-stone-100">{referrals.length}</p>
          </div>
        </div>
      </div>

      {/* Recent Orders Section */}
      <div className="bg-white dark:bg-[#16171b] rounded-3xl shadow-sm border border-stone-200 dark:border-stone-800 overflow-hidden">
        <div className="p-6 flex items-center justify-between border-b border-stone-100 dark:border-stone-800">
          <h2 className="text-base font-serif font-bold text-stone-900 dark:text-stone-100">
            Recent Orders
          </h2>
          <Link
            href="/account/orders"
            className="text-xs font-bold uppercase tracking-wider text-[#c46331] dark:text-amber-400 hover:underline flex items-center gap-1"
          >
            <span>View All Orders</span>
            <ArrowRight size={13} />
          </Link>
        </div>

        {recentOrders.length > 0 ? (
          <div className="divide-y divide-stone-100 dark:divide-stone-800">
            {recentOrders.map((order) => (
              <div key={order.id} className="p-6 flex flex-col sm:flex-row sm:items-center justify-between gap-4">
                <div>
                  <div className="flex items-center gap-3">
                    <span className="font-bold text-xs text-stone-900 dark:text-stone-100">
                      #{order.order_number}
                    </span>
                    <span className={cn("px-2.5 py-0.5 rounded-full text-[10px] font-bold uppercase tracking-wider", getStatusBadge(order.status))}>
                      {order.status.replace(/_/g, ' ')}
                    </span>
                  </div>
                  <p className="text-xs text-stone-400 mt-1">
                    {formatDate(order.created_at)} • {order.items.length} item(s)
                  </p>
                </div>

                <div className="flex items-center gap-4">
                  <span className="text-sm font-bold text-stone-900 dark:text-stone-100">
                    {formatAmount(order.total_amount)}
                  </span>
                  <Link
                    href={`/track-order?orderNumber=${order.order_number}&email=${encodeURIComponent(user.email)}`}
                    className="px-3.5 py-2 bg-stone-100 dark:bg-stone-800 hover:bg-[#c46331] hover:text-white rounded-xl text-xs font-semibold transition-colors flex items-center gap-1.5"
                  >
                    <Truck size={13} />
                    <span>Track</span>
                  </Link>
                </div>
              </div>
            ))}
          </div>
        ) : (
          <div className="p-12 text-center space-y-3">
            <ShoppingBag className="w-10 h-10 text-stone-300 dark:text-stone-700 mx-auto" />
            <p className="text-xs text-stone-500 dark:text-stone-400">No orders placed yet.</p>
            <Link
              href="/shop"
              className="inline-block px-6 py-2.5 bg-[#1a1714] text-white rounded-xl text-xs font-bold uppercase tracking-wider hover:bg-[#c46331] transition-colors"
            >
              Explore Boutique Collection →
            </Link>
          </div>
        )}
      </div>
    </div>
  );
}

'use client';

import React, { useEffect, useState } from 'react';
import { useAuth } from '@/lib/context/AuthContext';
import { DataStore } from '@/lib/store/data-store';
import { Referral } from '@/types';
import { formatDate } from '@/lib/utils';
import { Share2, Copy, CheckCircle2, Users, Gift, Mail, MessageCircle, Sparkles } from 'lucide-react';
import { cn } from '@/lib/utils';

export default function ReferralsPage() {
  const { user } = useAuth();
  const [referrals, setReferrals] = useState<Referral[]>([]);
  const [copied, setCopied] = useState(false);
  const settings = DataStore.getSettings();

  useEffect(() => {
    if (user) {
      const data = DataStore.getReferrals(user.id);
      data.sort((a, b) => new Date(b.created_at).getTime() - new Date(a.created_at).getTime());
      setReferrals(data);
    }
  }, [user]);

  if (!user) return null;

  const referralUrl = typeof window !== 'undefined' 
    ? `${window.location.origin}/auth/signup?ref=${user.referral_code}`
    : `https://ozeira.com/auth/signup?ref=${user.referral_code}`;

  const handleCopy = () => {
    navigator.clipboard.writeText(referralUrl);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const shareText = `Discover bespoke luxury at Ozeira. Sign up with my link to claim ₹500 off your first handcrafted creation: ${referralUrl}`;

  const totalReferrals = referrals.length;
  const rewardedReferrals = referrals.filter(r => r.status === 'rewarded').length;
  const pendingReferrals = totalReferrals - rewardedReferrals;

  return (
    <div className="space-y-6">
      <div>
        <h1 className="text-2xl font-serif font-bold text-stone-900 dark:text-stone-100 mb-1">
          Refer & Earn Privileges
        </h1>
        <p className="text-xs text-stone-500 dark:text-stone-400">
          Share your love for Ozeira craftsmanship and earn reward points for every invited patron.
        </p>
      </div>

      <div className="bg-white dark:bg-[#16171b] rounded-3xl shadow-sm border border-stone-200 dark:border-stone-800 overflow-hidden">
        <div className="bg-amber-50/50 dark:bg-amber-950/20 p-8 md:p-10 text-center border-b border-stone-100 dark:border-stone-800">
          <div className="w-14 h-14 bg-amber-100 dark:bg-amber-950/60 text-[#c46331] rounded-2xl flex items-center justify-center mx-auto mb-3 shadow-xs">
            <Gift size={26} />
          </div>
          <h2 className="text-xl font-serif font-bold text-stone-900 dark:text-stone-100 mb-2">
            Give ₹500, Earn {settings.loyalty?.referralBonusPoints || 500} Points
          </h2>
          <p className="text-xs text-stone-500 dark:text-stone-400 max-w-md mx-auto leading-relaxed">
            Invite your friends to the Ozeira atelier. They unlock ₹500 off their first order, and you earn {settings.loyalty?.referralBonusPoints || 500} points when their order is fulfilled.
          </p>
        </div>

        {/* Share Referral Link Input */}
        <div className="p-6 md:p-8 space-y-6">
          <div className="max-w-xl mx-auto space-y-2">
            <label className="block text-xs font-semibold text-stone-700 dark:text-stone-300">
              Your Exclusive Invitation Link
            </label>
            <div className="flex gap-2">
              <input
                type="text"
                readOnly
                value={referralUrl}
                className="w-full px-4 py-2.5 bg-stone-50 dark:bg-stone-900 border border-stone-200 dark:border-stone-700 rounded-xl text-xs font-mono text-stone-900 dark:text-stone-100 focus:outline-none"
              />
              <button
                onClick={handleCopy}
                className="px-5 py-2.5 bg-[#1a1714] dark:bg-stone-800 hover:bg-[#c46331] text-white rounded-xl text-xs font-bold uppercase tracking-wider transition-colors flex items-center gap-1.5 shrink-0 cursor-pointer"
              >
                {copied ? <CheckCircle2 size={14} className="text-emerald-400" /> : <Copy size={14} />}
                <span>{copied ? 'Copied' : 'Copy'}</span>
              </button>
            </div>
          </div>

          {/* Social Share Buttons */}
          <div className="flex justify-center gap-3">
            <a
              href={`https://wa.me/?text=${encodeURIComponent(shareText)}`}
              target="_blank"
              rel="noopener noreferrer"
              className="px-4 py-2 bg-emerald-600 hover:bg-emerald-700 text-white rounded-xl text-xs font-semibold flex items-center gap-2 transition-colors"
            >
              <MessageCircle size={14} />
              <span>Share on WhatsApp</span>
            </a>
            <a
              href={`mailto:?subject=An invitation to Ozeira Atelier&body=${encodeURIComponent(shareText)}`}
              className="px-4 py-2 bg-stone-100 dark:bg-stone-800 hover:bg-stone-200 dark:hover:bg-stone-700 text-stone-700 dark:text-stone-300 rounded-xl text-xs font-semibold flex items-center gap-2 transition-colors"
            >
              <Mail size={14} />
              <span>Email Friend</span>
            </a>
          </div>
        </div>
      </div>

      {/* Referral Stats */}
      <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
        <div className="bg-white dark:bg-[#16171b] p-5 rounded-3xl border border-stone-200 dark:border-stone-800 shadow-sm text-center">
          <p className="text-[11px] font-semibold text-stone-500 dark:text-stone-400 uppercase tracking-wider">Total Invited</p>
          <p className="text-2xl font-bold text-stone-900 dark:text-stone-100 mt-1">{totalReferrals}</p>
        </div>
        <div className="bg-white dark:bg-[#16171b] p-5 rounded-3xl border border-stone-200 dark:border-stone-800 shadow-sm text-center">
          <p className="text-[11px] font-semibold text-stone-500 dark:text-stone-400 uppercase tracking-wider">Orders Completed</p>
          <p className="text-2xl font-bold text-emerald-600 dark:text-emerald-400 mt-1">{rewardedReferrals}</p>
        </div>
        <div className="bg-white dark:bg-[#16171b] p-5 rounded-3xl border border-stone-200 dark:border-stone-800 shadow-sm text-center">
          <p className="text-[11px] font-semibold text-stone-500 dark:text-stone-400 uppercase tracking-wider">Points Earned</p>
          <p className="text-2xl font-bold text-[#c46331] dark:text-amber-400 mt-1">
            {rewardedReferrals * (settings.loyalty?.referralBonusPoints || 500)}
          </p>
        </div>
      </div>

      {/* Referral Activity List */}
      <div className="bg-white dark:bg-[#16171b] rounded-3xl shadow-sm border border-stone-200 dark:border-stone-800 overflow-hidden">
        <div className="p-6 border-b border-stone-100 dark:border-stone-800 flex items-center gap-2">
          <Users size={16} className="text-[#c46331]" />
          <h2 className="text-sm font-bold text-stone-900 dark:text-stone-100">
            Invited Patrons History
          </h2>
        </div>

        {referrals.length > 0 ? (
          <div className="divide-y divide-stone-100 dark:divide-stone-800">
            {referrals.map((ref) => (
              <div key={ref.id} className="p-5 flex items-center justify-between gap-4">
                <div>
                  <p className="text-xs font-semibold text-stone-900 dark:text-stone-100">{ref.referee_email}</p>
                  <p className="text-[11px] text-stone-400 mt-0.5">Invited on {formatDate(ref.created_at)}</p>
                </div>
                <span className={cn(
                  "px-2.5 py-0.5 rounded-full text-[10px] font-bold uppercase tracking-wider",
                  ref.status === 'rewarded' 
                    ? "bg-emerald-50 dark:bg-emerald-950/40 text-emerald-600 dark:text-emerald-400" 
                    : "bg-amber-50 dark:bg-amber-950/40 text-amber-600 dark:text-amber-400"
                )}>
                  {ref.status === 'rewarded' ? 'Reward Granted (+500 Pts)' : 'Pending Order'}
                </span>
              </div>
            ))}
          </div>
        ) : (
          <div className="p-12 text-center text-xs text-stone-400">
            No friends invited yet. Share your link above to start earning rewards!
          </div>
        )}
      </div>
    </div>
  );
}

'use client';

import React, { useState, useEffect } from 'react';
import { useAuth } from '@/lib/context/AuthContext';
import { Save, AlertTriangle, User, Lock, Bell, CheckCircle2 } from 'lucide-react';
import { cn } from '@/lib/utils';

export default function SettingsPage() {
  const { user, updateProfile } = useAuth();
  const [loading, setLoading] = useState(false);
  const [successMsg, setSuccessMsg] = useState('');

  // Profile Form
  const [formData, setFormData] = useState({
    full_name: '',
    phone: '',
  });

  // Password Form
  const [passData, setPassData] = useState({
    current: '',
    new: '',
    confirm: ''
  });

  // Notifications Form
  const [notifications, setNotifications] = useState({
    email: true,
    sms: false,
    push: false
  });

  useEffect(() => {
    if (user) {
      setFormData({
        full_name: user.full_name,
        phone: user.phone || '',
      });

      const savedPrefs = localStorage.getItem('ozeira_notif_prefs');
      if (savedPrefs) {
        setNotifications(JSON.parse(savedPrefs));
      }
    }
  }, [user]);

  if (!user) return null;

  const handleProfileSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    const success = await updateProfile({
      full_name: formData.full_name,
      phone: formData.phone
    });
    setLoading(false);

    if (success) {
      showSuccess('Profile details updated successfully!');
    }
  };

  const handlePasswordSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (passData.new !== passData.confirm) {
      alert("New passwords do not match.");
      return;
    }
    if (passData.new.length < 6) {
      alert("Password should be at least 6 characters.");
      return;
    }
    setPassData({ current: '', new: '', confirm: '' });
    showSuccess('Password updated successfully!');
  };

  const handleNotificationChange = (key: keyof typeof notifications) => {
    const newPrefs = { ...notifications, [key]: !notifications[key] };
    setNotifications(newPrefs);
    localStorage.setItem('ozeira_notif_prefs', JSON.stringify(newPrefs));
    showSuccess('Notification preferences saved.');
  };

  const showSuccess = (msg: string) => {
    setSuccessMsg(msg);
    setTimeout(() => setSuccessMsg(''), 3500);
  };

  return (
    <div className="space-y-8 relative">
      {/* Toast */}
      {successMsg && (
        <div className="fixed bottom-6 right-6 bg-[#1a1714] text-white px-5 py-3 rounded-2xl shadow-xl font-medium text-xs z-50 animate-fade-in-up border border-stone-700 flex items-center gap-2">
          <CheckCircle2 size={16} className="text-emerald-400" />
          <span>{successMsg}</span>
        </div>
      )}

      <div>
        <h1 className="text-2xl font-serif font-bold text-stone-900 dark:text-stone-100 mb-1">Account Settings</h1>
        <p className="text-xs text-stone-500 dark:text-stone-400">Update your profile credentials, security, and notification channels.</p>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        <div className="lg:col-span-2 space-y-8">

          {/* Profile Section */}
          <div className="bg-white dark:bg-[#16171b] rounded-3xl shadow-sm border border-stone-200 dark:border-stone-800 p-6 md:p-8 space-y-6">
            <div className="flex items-center gap-2 pb-3 border-b border-stone-100 dark:border-stone-800">
              <User size={16} className="text-[#c46331]" />
              <h2 className="text-sm font-bold text-stone-900 dark:text-stone-100">Personal Information</h2>
            </div>

            <form onSubmit={handleProfileSubmit} className="space-y-4 text-xs">
              <div>
                <label className="block font-semibold text-stone-700 dark:text-stone-300 mb-1.5">Full Name *</label>
                <input
                  type="text"
                  required
                  value={formData.full_name}
                  onChange={(e) => setFormData({ ...formData, full_name: e.target.value })}
                  className="w-full px-4 py-2.5 bg-stone-50 dark:bg-stone-900 border border-stone-200 dark:border-stone-700 rounded-xl text-stone-900 dark:text-stone-100 focus:outline-none focus:border-[#c46331]"
                />
              </div>

              <div>
                <label className="block font-semibold text-stone-700 dark:text-stone-300 mb-1.5">Email Address</label>
                <input
                  type="email"
                  disabled
                  value={user.email}
                  className="w-full px-4 py-2.5 bg-stone-100 dark:bg-stone-800 border border-stone-200 dark:border-stone-700 rounded-xl text-stone-500 dark:text-stone-400 cursor-not-allowed"
                />
                <span className="text-[10px] text-stone-400 mt-1 block">Email address cannot be modified once verified.</span>
              </div>

              <div>
                <label className="block font-semibold text-stone-700 dark:text-stone-300 mb-1.5">Phone Number</label>
                <input
                  type="tel"
                  value={formData.phone}
                  onChange={(e) => setFormData({ ...formData, phone: e.target.value })}
                  placeholder="e.g. +91 9876543210"
                  className="w-full px-4 py-2.5 bg-stone-50 dark:bg-stone-900 border border-stone-200 dark:border-stone-700 rounded-xl text-stone-900 dark:text-stone-100 focus:outline-none focus:border-[#c46331]"
                />
              </div>

              <div className="pt-2">
                <button
                  type="submit"
                  disabled={loading}
                  className="px-6 py-2.5 bg-[#1a1714] dark:bg-stone-800 hover:bg-[#c46331] text-white rounded-xl text-xs font-bold uppercase tracking-wider transition-colors disabled:opacity-50 cursor-pointer shadow-sm"
                >
                  {loading ? 'Saving...' : 'Save Profile Details'}
                </button>
              </div>
            </form>
          </div>

          {/* Security Section */}
          <div className="bg-white dark:bg-[#16171b] rounded-3xl shadow-sm border border-stone-200 dark:border-stone-800 p-6 md:p-8 space-y-6">
            <div className="flex items-center gap-2 pb-3 border-b border-stone-100 dark:border-stone-800">
              <Lock size={16} className="text-[#c46331]" />
              <h2 className="text-sm font-bold text-stone-900 dark:text-stone-100">Security & Password</h2>
            </div>

            <form onSubmit={handlePasswordSubmit} className="space-y-4 text-xs">
              <div>
                <label className="block font-semibold text-stone-700 dark:text-stone-300 mb-1.5">New Password</label>
                <input
                  type="password"
                  required
                  placeholder="••••••••"
                  value={passData.new}
                  onChange={(e) => setPassData({ ...passData, new: e.target.value })}
                  className="w-full px-4 py-2.5 bg-stone-50 dark:bg-stone-900 border border-stone-200 dark:border-stone-700 rounded-xl text-stone-900 dark:text-stone-100 focus:outline-none focus:border-[#c46331]"
                />
              </div>

              <div>
                <label className="block font-semibold text-stone-700 dark:text-stone-300 mb-1.5">Confirm New Password</label>
                <input
                  type="password"
                  required
                  placeholder="••••••••"
                  value={passData.confirm}
                  onChange={(e) => setPassData({ ...passData, confirm: e.target.value })}
                  className="w-full px-4 py-2.5 bg-stone-50 dark:bg-stone-900 border border-stone-200 dark:border-stone-700 rounded-xl text-stone-900 dark:text-stone-100 focus:outline-none focus:border-[#c46331]"
                />
              </div>

              <div className="pt-2">
                <button
                  type="submit"
